-- ============================================================
-- Full Content Setup
-- Run this in Supabase SQL Editor once
-- Creates Blog + Glossary tables, inserts all content
-- ============================================================

-- ======== NEW TABLES ========

-- Blog Posts
CREATE TABLE IF NOT EXISTS "BlogPost" (
    id TEXT PRIMARY KEY,
    slug TEXT UNIQUE NOT NULL,
    title TEXT NOT NULL,
    description TEXT NOT NULL,
    content TEXT,
    author TEXT,
    featured_image TEXT,
    category TEXT,
    status "ContentStatus" NOT NULL DEFAULT 'DRAFT',
    published_at TIMESTAMP(3),
    created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP(3) NOT NULL
);
CREATE INDEX IF NOT EXISTS "BlogPost_status_publishedAt_idx" ON "BlogPost"(status, published_at);

-- Glossary Terms
CREATE TABLE IF NOT EXISTS "GlossaryTerm" (
    id TEXT PRIMARY KEY,
    slug TEXT UNIQUE NOT NULL,
    term TEXT NOT NULL,
    definition TEXT NOT NULL,
    long_definition TEXT,
    category TEXT,
    related_slugs JSONB,
    status "ContentStatus" NOT NULL DEFAULT 'PUBLISHED',
    created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP(3) NOT NULL
);
CREATE INDEX IF NOT EXISTS "GlossaryTerm_status_idx" ON "GlossaryTerm"(status);
CREATE INDEX IF NOT EXISTS "GlossaryTerm_category_idx" ON "GlossaryTerm"(category);

-- Disable RLS for new tables
ALTER TABLE IF EXISTS "BlogPost" DISABLE ROW LEVEL SECURITY;
ALTER TABLE IF EXISTS "GlossaryTerm" DISABLE ROW LEVEL SECURITY;

-- ======== BLOG POSTS ========

DELETE FROM "BlogPost";

INSERT INTO "BlogPost" (id, slug, title, description, content, author, category, status, published_at, created_at, updated_at) VALUES
('blog-001', 'ai-transforming-real-estate-2025', 'How AI Is Transforming Real Estate in 2025', 'From automated valuations to virtual staging, AI is reshaping every corner of the real estate industry.', '<h2>The AI Revolution Has Arrived</h2><p>In 2025, artificial intelligence is no longer a futuristic concept in real estate — it is a competitive necessity. According to the National Association of Realtors, <strong>47% of agents now use AI tools</strong> in their daily workflow, up from just 28% in 2023.</p><h2>Key Areas of Transformation</h2><h3>Property Valuation</h3><p>Automated Valuation Models (AVMs) powered by machine learning now rival traditional appraisals in accuracy for standard residential properties. Zillow Zestimate and Quantarium analyze thousands of data points — from public records to satellite imagery — to generate real-time valuations.</p><h3>Marketing and Virtual Staging</h3><p>AI virtual staging tools like Styldod can digitally furnish an empty room in minutes for under $16, compared to $1,500-$3,000 per month for traditional staging. Listings with AI-staged photos receive 40% more online views.</p><h3>Lead Generation</h3><p>Predictive analytics platforms like Revaluate identify homeowners most likely to move, while AI-powered CRM systems like CINC automatically nurture leads through personalized communication sequences. Top-performing teams using AI report 3.2x more closed transactions.</p><h2>The Bottom Line</h2><p>The agents who embrace AI now are building an unassailable competitive advantage. AI handles data processing and lead qualification so you can focus on relationships and strategy.</p>', 'Alex Chen, Lead Researcher', 'Trends', 'PUBLISHED', NOW(), NOW(), NOW());

INSERT INTO "BlogPost" (id, slug, title, description, content, author, category, status, published_at, created_at, updated_at) VALUES
('blog-002', 'top-ai-tools-real-estate-agents', 'Top 10 AI Tools Every Real Estate Agent Needs in 2025', 'The best AI-powered platforms for property valuation, lead generation, virtual staging, and more.', '<h2>Essential AI Tools</h2><p>The real estate AI landscape is growing fast. We have curated the top 10 AI tools across five essential categories.</p><h2>Property Valuation</h2><h3>1. Zillow AI (Zestimate)</h3><p>The most widely used AVM, covering 100M+ U.S. homes. Free, real-time valuations with 2.4% median error rate.</p><h3>2. Quantarium</h3><p>Enterprise-grade AVM with satellite imagery analysis. Top-5 accuracy in Freddie Mac assessments. Best for institutional users.</p><h2>Lead Generation</h2><h3>3. Revaluate</h3><p>AI predicts likely movers using 2,000+ data points. Users report 2-3x higher conversion rates vs. purchased leads.</p><h3>4. CINC</h3><p>AI-powered lead scoring and automated multi-channel nurturing. Handles two-way SMS conversations automatically.</p><h2>Marketing</h2><h3>5. Styldod</h3><p>AI virtual staging ($16/image), image enhancement, floor plans, and listing descriptions.</p><h3>6. Matterport</h3><p>3D digital twins with Cortex AI. Listings with Matterport tours generate 49% more qualified leads.</p><h2>Analytics & Search</h2><h3>7. HouseCanary</h3><p>Institutional-grade analytics with 3-year value forecasting.</p><h3>8. Plunk</h3><p>Real-time valuation with renovation ROI calculator.</p><h3>9. Restb.ai</h3><p>Computer vision AI for property photo analysis and MLS compliance.</p><h3>10. Mosaik</h3><p>AI-driven neighborhood matching based on lifestyle preferences.</p>', 'Morgan Taylor, Senior Editor', 'Tools', 'PUBLISHED', NOW(), NOW(), NOW());

INSERT INTO "BlogPost" (id, slug, title, description, content, author, category, status, published_at, created_at, updated_at) VALUES
('blog-003', 'ai-property-valuation-accuracy', 'AI Property Valuation: How Accurate Are AVMs in 2025?', 'A deep dive into AVM accuracy — when you can trust an AI valuation vs. a traditional appraisal.', '<h2>AVM Accuracy in 2025</h2><p>The best AVMs now achieve <strong>median error rates of 2-3%</strong> in well-covered urban and suburban markets. However, accuracy varies significantly by data availability and property type.</p><h2>How AVMs Work</h2><p>Modern AVMs combine comparable sales analysis, hedonic regression modeling, and machine learning. Advanced models like Quantarium also incorporate satellite imagery and computer vision.</p><h2>Accuracy by Market</h2><ul><li><strong>Urban/suburban, good data</strong>: 2-3% median error — reliable for listing discussions</li><li><strong>Rural, limited data</strong>: 7-10% error — use as a starting point only</li><li><strong>Non-disclosure states</strong>: 5-8% error — tax assessment data may be stale</li><li><strong>Unique/custom homes</strong>: 8-15% error — lack of good comparable sales</li></ul><h2>When to Trust an AVM</h2><p>AVMs are reliable for: listing price guidance, buyer consultations, market trend analysis, and portfolio monitoring. They should NOT be the sole method for: final mortgage approval, estate settlement, or luxury properties with no comparables.</p>', 'Dr. Sarah Park, Data Science Editor', 'Technology', 'PUBLISHED', NOW(), NOW(), NOW());

INSERT INTO "BlogPost" (id, slug, title, description, content, author, category, status, published_at, created_at, updated_at) VALUES
('blog-004', 'ai-lead-generation-real-estate', 'The Ultimate Guide to AI-Powered Lead Generation', 'How predictive analytics and automated nurturing help agents find and convert more leads with less effort.', '<h2>Why Traditional Lead Gen Fails</h2><p>The average agent spends 30-40% of time on lead generation, yet conversion rates on purchased leads average just 0.5-2%. AI changes this by identifying the right people at the right time.</p><h2>Predictive Seller Identification</h2><p>Revaluate analyzes thousands of data points per household to predict which homeowners are most likely to move in 6-12 months. Agents using this approach report 2-3x higher conversion rates.</p><h2>AI Lead Scoring</h2><p>Platforms like CINC analyze behavioral signals — email opens, property views, SMS responses — to rank leads by conversion likelihood. Teams see 30-40% improvement in lead-to-appointment rates.</p><h2>Automated Nurturing</h2><p>AI handles multi-channel follow-up: personalized emails, SMS drip campaigns, and automated call reminders. The result: 3-5x ROI through improved conversion of leads that would have gone cold.</p>', 'Jordan Kim, Growth Strategist', 'Guides', 'PUBLISHED', NOW(), NOW(), NOW());

INSERT INTO "BlogPost" (id, slug, title, description, content, author, category, status, published_at, created_at, updated_at) VALUES
('blog-005', 'virtual-staging-vs-traditional-staging', 'Virtual Staging vs Traditional Staging: AI Comparison', 'Compare cost, speed, buyer perception, and ROI to decide which staging approach fits your listings.', '<h2>The Staging Revolution</h2><p>Traditional staging costs $1,500-$3,000/month with multi-week lead times. AI virtual staging starts at $16/image with turnaround in minutes.</p><h2>Cost Comparison</h2><ul><li><strong>Traditional</strong>: $1,500-$3,000/month plus furniture rental and setup fees</li><li><strong>AI (Styldod)</strong>: $16/image or $99-$249/month subscription</li><li><strong>Annual savings for 12 listings/year</strong>: $15,000-$30,000</li></ul><h2>Buyer Perception</h2><p>Listings with staged photos receive 40% more online views. At thumbnail size, AI-staged images are virtually indistinguishable from traditionally staged photos.</p><h2>When to Use Each</h2><p><strong>Traditional staging</strong>: luxury homes ($2M+), in-person open houses, sellers with premium budget.</p><p><strong>AI staging</strong>: vacant properties needing fast marketing, limited budget, multiple design style options.</p>', 'Riley Chen, Design 'Editorial Team', 'Marketing' Visuals Editor', 'Marketing', 'PUBLISHED', NOW(), NOW(), NOW());

INSERT INTO "BlogPost" (id, slug, title, description, content, author, category, status, published_at, created_at, updated_at) VALUES
('blog-006', 'nlp-real-estate-beginners-guide', 'What Is NLP? A Beginner''s Guide to Natural Language Processing', 'How NLP powers AI property search, listing descriptions, and chatbots in real estate.', '<h2>NLP: AI That Understands Language</h2><p>Natural Language Processing enables computers to understand, interpret, and generate human language. In real estate, NLP powers natural language search, listing descriptions, chatbots, and sentiment analysis.</p><h2>Natural Language Search</h2><p>Buyers can search with phrases like "3-bedroom Craftsman with a large backyard under $600K" — NLP extracts property type, features, price, location, and qualitative preferences.</p><h2>Automated Listing Descriptions</h2><p>NLP generates MLS-optimized listing descriptions that are both keyword-rich for search and engaging for readers. Platforms like Styldod produce unique descriptions in seconds.</p><h2>AI Chatbots</h2><p>NLP-powered chatbots handle buyer inquiries 24/7 — answering property questions, scheduling showings, and qualifying leads. They improve with every conversation.</p><h2>The Future</h2><p>Expect NLP to soon handle offer negotiation, contract review, and comprehensive property reports synthesized from multiple data sources.</p>', 'Taylor Brooks, Technology Writer', 'Education', 'PUBLISHED', NOW(), NOW(), NOW());

