INSERT INTO "GlossaryTerm" (id, slug, term, definition, long_definition, category, related_slugs, status, created_at, updated_at) VALUES
('gloss-001', 'avm-automated-valuation-model', 'AVM (Automated Valuation Model)', 'An AI-powered system that estimates property values by analyzing data from public records, recent sales, and market trends.', 'AVMs use machine learning to estimate property market values by analyzing thousands of data points including comparable sales, property characteristics, and market trends. Major AVMs include Zillow Zestimate (100M+ homes, 2.4% median error) and Quantarium (150M+ properties with satellite imagery).', 'Property Valuation', '["predictive-analytics","machine-learning","cma"]', 'PUBLISHED', NOW(), NOW());

INSERT INTO "GlossaryTerm" (id, slug, term, definition, long_definition, category, related_slugs, status, created_at, updated_at) VALUES
('gloss-002', 'predictive-analytics', 'Predictive Analytics', 'The use of AI and statistical algorithms to identify future outcomes based on historical data.', 'Predictive analytics combines historical transaction data, property characteristics, and consumer behavior to forecast outcomes like seller likelihood and market trends. Platforms like Revaluate analyze 2,000+ data points per household, achieving 70-80% move prediction accuracy.', 'Data Science', '["machine-learning","lead-scoring","avm"]', 'PUBLISHED', NOW(), NOW());

INSERT INTO "GlossaryTerm" (id, slug, term, definition, long_definition, category, related_slugs, status, created_at, updated_at) VALUES
('gloss-003', 'nlp-natural-language-processing', 'NLP (Natural Language Processing)', 'A branch of AI enabling computers to understand and generate human language.', 'NLP powers natural language property search, automated listing descriptions, AI chatbots for buyer inquiries, and sentiment analysis of lead communications. Used by platforms like Zillow, Styldod, and Mosaik.', 'AI Technology', '["machine-learning","deep-learning"]', 'PUBLISHED', NOW(), NOW());

INSERT INTO "GlossaryTerm" (id, slug, term, definition, long_definition, category, related_slugs, status, created_at, updated_at) VALUES
('gloss-004', 'computer-vision', 'Computer Vision', 'AI technology that analyzes visual information from images and videos.', 'Computer vision in real estate identifies room types, architectural features, and property conditions from photos. Restb.ai recognizes 100+ property features for MLS compliance, visual search, and appraisal support.', 'AI Technology', '["deep-learning","digital-twin","3d-rendering"]', 'PUBLISHED', NOW(), NOW());

INSERT INTO "GlossaryTerm" (id, slug, term, definition, long_definition, category, related_slugs, status, created_at, updated_at) VALUES
('gloss-005', 'digital-twin', 'Digital Twin', 'A virtual 3D replica of a physical property enabling remote walkthroughs and spatial analysis.', 'Digital twins enable immersive virtual tours, automated floor plans with measurements, and remote property inspection. Matterport leads with 10M+ spaces captured and Cortex AI for automatic room/object recognition.', 'Virtual Reality', '["3d-rendering","computer-vision"]', 'PUBLISHED', NOW(), NOW());

INSERT INTO "GlossaryTerm" (id, slug, term, definition, long_definition, category, related_slugs, status, created_at, updated_at) VALUES
('gloss-006', 'lead-scoring', 'Lead Scoring', 'AI-driven method of ranking sales leads by conversion likelihood based on behavioral data.', 'AI analyzes email opens, property views, SMS responses, and website visits to assign real-time conversion probability scores. CINC reports 30-40% improvement in lead-to-appointment rates with AI scoring.', 'CRM', '["predictive-analytics","automated-nurture-sequence"]', 'PUBLISHED', NOW(), NOW());

INSERT INTO "GlossaryTerm" (id, slug, term, definition, long_definition, category, related_slugs, status, created_at, updated_at) VALUES
('gloss-007', 'automated-nurture-sequence', 'Automated Nurture Sequence', 'AI-driven communications (email, SMS, calls) that automatically engage and qualify leads.', 'Automated nurture replaces manual follow-up with AI-orchestrated multi-channel flows. CINC AI Personal Assistant conducts two-way SMS conversations, answers questions, and schedules appointments. Teams report 3-5x ROI.', 'CRM', '["lead-scoring","predictive-analytics"]', 'PUBLISHED', NOW(), NOW());

INSERT INTO "GlossaryTerm" (id, slug, term, definition, long_definition, category, related_slugs, status, created_at, updated_at) VALUES
('gloss-008', 'roi-analysis', 'ROI Analysis', 'Calculation of return on investment — AI-enhanced to factor in market trends and appreciation forecasts.', 'AI ROI tools like Plunk and HouseCanary evaluate renovation ROI, rental income projections, portfolio performance, and buy-vs-rent analysis with far more variables than manual spreadsheet models.', 'Analytics', '["predictive-analytics","avm"]', 'PUBLISHED', NOW(), NOW());

INSERT INTO "GlossaryTerm" (id, slug, term, definition, long_definition, category, related_slugs, status, created_at, updated_at) VALUES
('gloss-009', 'virtual-staging', 'Virtual Staging', 'The use of AI to digitally furnish and decorate empty rooms in property photos.', 'AI virtual staging analyzes room dimensions and lighting to digitally insert furniture at correct scale. Styldod offers staging from $16/image vs $1,500-$3,000/month traditional. Listings with staged photos get 40% more views.', 'Marketing', '["computer-vision","3d-rendering"]', 'PUBLISHED', NOW(), NOW());

INSERT INTO "GlossaryTerm" (id, slug, term, definition, long_definition, category, related_slugs, status, created_at, updated_at) VALUES
('gloss-010', 'geospatial-analytics', 'Geospatial Analytics', 'AI-powered analysis of location-based data combining satellite imagery, mapping, and property records.', 'Geospatial analytics integrates satellite imagery, GIS mapping, and demographic databases for property assessment at scale. Quantarium uses this as a key differentiator for valuing properties where traditional data is sparse.', 'Data Science', '["predictive-analytics","computer-vision","avm"]', 'PUBLISHED', NOW(), NOW());

INSERT INTO "GlossaryTerm" (id, slug, term, definition, long_definition, category, related_slugs, status, created_at, updated_at) VALUES
('gloss-011', '3d-rendering', '3D Rendering', 'The process of creating photorealistic images from 3D models for property marketing.', '3D rendering powers Matterport virtual tours, architectural visualization, virtual renovation previews, and commercial property fly-throughs. AI has dramatically reduced rendering time from hours to seconds per frame.', 'Virtual Reality', '["digital-twin","virtual-staging"]', 'PUBLISHED', NOW(), NOW());

INSERT INTO "GlossaryTerm" (id, slug, term, definition, long_definition, category, related_slugs, status, created_at, updated_at) VALUES
('gloss-012', 'machine-learning', 'Machine Learning', 'Core AI technology where algorithms improve through experience by analyzing data patterns.', 'Machine learning powers AVMs, predictive seller identification, property recommendation engines, and computer vision for photo analysis. It identifies complex, non-linear relationships across thousands of variables that traditional methods miss.', 'AI Technology', '["deep-learning","predictive-analytics","nlp"]', 'PUBLISHED', NOW(), NOW());

INSERT INTO "GlossaryTerm" (id, slug, term, definition, long_definition, category, related_slugs, status, created_at, updated_at) VALUES
('gloss-013', 'deep-learning', 'Deep Learning', 'Advanced machine learning using multi-layered neural networks for complex AI applications.', 'Deep learning powers computer vision that recognizes 100+ property features in photos, natural language models for listing descriptions and chatbots, and valuation models analyzing satellite imagery. It improves with more data, benefiting large-scale platforms.', 'AI Technology', '["machine-learning","computer-vision","nlp"]', 'PUBLISHED', NOW(), NOW());

INSERT INTO "GlossaryTerm" (id, slug, term, definition, long_definition, category, related_slugs, status, created_at, updated_at) VALUES
('gloss-014', 'cma', 'Comparative Market Analysis (CMA)', 'A method of estimating property value by comparing to similar recently sold properties — increasingly AI-enhanced.', 'AI-enhanced CMAs instantly identify the most relevant comps, adjust for feature differences, weight by recency and proximity, and generate professional reports in minutes. Combines algorithmic analysis with agent expertise for listing presentations.', 'Property Valuation', '["avm","predictive-analytics"]', 'PUBLISHED', NOW(), NOW());

INSERT INTO "GlossaryTerm" (id, slug, term, definition, long_definition, category, related_slugs, status, created_at, updated_at) VALUES
('gloss-015', 'proptech', 'PropTech', 'Property Technology — software and tools that innovate in the real estate industry.', 'PropTech encompasses AI valuation, virtual tours, digital transactions, smart home tech, and property management software. The sector attracted $15B+ in VC funding in 2024. AI is the fastest-growing segment within PropTech.', 'Industry', '["avm","machine-learning","digital-twin"]', 'PUBLISHED', NOW(), NOW());

-- ======== CONTENT UPDATES (Tutorials, Comparisons, Stats) ========

-- Tutorial 1: Getting Started with Zillow AI
UPDATE "Tutorial" SET content = '<h2>Step 1: Create Your Zillow Account</h2><p>Start by visiting Zillow.com and signing up for a free account. A free account gives you access to basic property search and the Zestimate valuation tool.</p><ul><li>Click <strong>Sign Up</strong> in the top right corner</li><li>Enter your email and create a password</li><li>Verify your email via the confirmation link</li><li>Complete your profile with your license number (if applicable)</li></ul><h2>Step 2: Navigate the Dashboard</h2><p>Once logged in, you will land on the Zillow dashboard. Key sections include:</p><ul><li><strong>Buy</strong> — Search homes with advanced filters</li><li><strong>Rent</strong> — Browse rental listings</li><li><strong>Sell</strong> — Zestimate tool and listing resources</li><li><strong>Home Loans</strong> — Mortgage calculators</li><li><strong>Agent Finder</strong> — AI-powered agent matching</li></ul><h2>Step 3: Master the Zestimate Tool</h2><p>The Zestimate is Zillow AI-powered AVM covering over 100 million U.S. homes. To use it effectively:</p><ul><li>Search any property by address</li><li>Review the <strong>Zestimate history</strong> chart (1, 5, and 10-year trends)</li><li>Check the <strong>Zestimate range</strong> for valuation uncertainty</li><li>Compare against the listing price or tax assessment</li></ul><h2>Step 4: Use AI-Powered Property Search</h2><p>Zillow natural language search allows you to describe what you want in plain English:</p><ul><li>Search phrases like "3-bedroom homes with a pool under $500k in Austin"</li><li>Apply filters: price, home type, square footage, year built</li><li>Use <strong>Map View</strong> to draw custom search boundaries</li><li>Save searches and set up <strong>Instant Alerts</strong></li></ul><h2>Step 5: Leverage Market Analysis Features</h2><ul><li><strong>Market Reports</strong> — Monthly data on prices, days on market, and inventory</li><li><strong>Neighborhood Insights</strong> — School ratings, walk scores, transit scores</li><li><strong>Comparable Sales</strong> — View recently sold similar properties</li></ul><h2>Step 6: Integrate with Your Workflow</h2><ul><li>Connect Zillow with your CRM via <strong>Zillow Tech Connect</strong></li><li>Download the <strong>Zillow Premier Agent app</strong> for mobile access</li><li>Use <strong>My Listings</strong> dashboard to monitor performance</li><li>Review <strong>Contact Analytics</strong> to see which leads are most engaged</li><li>Export market reports as PDFs for client presentations</li></ul>' WHERE slug = 'getting-started-zillow-ai';

-- Tutorial 2: AI Virtual Staging
UPDATE "Tutorial" SET content = '<h2>Step 1: Understand AI Virtual Staging</h2><p>AI virtual staging uses machine learning to digitally furnish and decorate empty rooms. Unlike traditional staging that costs $1,500-$3,000 per month, AI staging starts at $16 per image with turnaround in minutes.</p><ul><li>AI analyzes room dimensions, lighting, and architectural features</li><li>Furniture and decor are rendered at the correct scale</li><li>Multiple design styles: Modern, Farmhouse, Minimalist, Scandinavian</li></ul><h2>Step 2: Set Up Your Styldod Account</h2><p>Go to Styldod.com and create an account:</p><ul><li>Choose a plan — Pay-as-you-go ($16/image), Pro ($99/month), or Team ($249/month)</li><li>Complete your profile with brokerage information</li><li>Familiarize yourself with the dashboard: Uploads, Orders, and Gallery</li></ul><h2>Step 3: Prepare Your Photos</h2><p>The quality of AI staging output depends on input photo quality:</p><ul><li><strong>High-resolution images</strong> — at least 2000px on the longest side</li><li><strong>Good lighting</strong> — natural daylight yields best results</li><li><strong>Wide angles</strong> — show as much of the room as possible</li><li><strong>Avoid clutter</strong> — remove personal items before photographing</li><li><strong>Keep vertical lines straight</strong> — use a tripod if possible</li></ul><h2>Step 4: Upload and Select Design Style</h2><ul><li>Click <strong>New Order</strong> and upload your property photos (up to 20 per batch)</li><li>Select room type: Living Room, Bedroom, Kitchen, Dining Room, Home Office</li><li>Choose a <strong>Design Style</strong> — Modern is most popular for broad appeal</li><li>Add optional notes for the AI</li><li>Review the order summary and submit</li></ul><h2>Step 5: Review and Refine Results</h2><ul><li>Review each staged image against the original for realism</li><li>Check for AI artifacts: distorted furniture, mismatched shadows</li><li>Use <strong>revision request</strong> if adjustments are needed</li><li>Download in web-optimized or print-quality resolution</li></ul><h2>Step 6: Optimize Your MLS Listing</h2><ul><li>Listings with virtual staging receive <strong>40% more online views</strong></li><li>Buyers spend <strong>3x longer</strong> viewing staged listing pages</li><li>Always <strong>disclose virtual staging</strong> in your listing notes</li><li>Include one original empty room photo for transparency</li></ul><h2>Step 7: Explore Additional Tools</h2><ul><li><strong>Image Enhancement</strong> — Auto-correct lighting and color balance</li><li><strong>Floor Plan Generation</strong> — Convert photos to 2D floor plans</li><li><strong>Listing Description Writer</strong> — AI-generated MLS descriptions</li><li><strong>Social Media Generator</strong> — Instagram and Facebook-ready posts</li></ul>' WHERE slug = 'virtual-staging-guide';

-- Tutorial 3: Matterport 3D Tours
UPDATE "Tutorial" SET content = '<h2>Step 1: Choose Your Matterport Camera</h2><p>Matterport supports a range of capture devices:</p><ul><li><strong>Matterport Pro3</strong> — Flagship 3D camera, best-in-class accuracy</li><li><strong>Matterport Pro2</strong> — Previous generation, excellent quality at lower price</li><li><strong>Smartphone (iPhone/Android)</strong> — Free Matterport Capture app</li><li><strong>Ricoh Theta / Insta360</strong> — Third-party 360 cameras via integrations</li><li><strong>Leica BLK360</strong> — Laser scanning for large commercial properties</li></ul><h2>Step 2: Plan Your Scan Strategy</h2><ul><li>Place scan points <strong>5-8 feet apart</strong> for optimal alignment</li><li>Each scan point must see at least two other positions</li><li>Scan all rooms: bathrooms, closets, laundry, garage</li><li>Include outdoor spaces: patios, decks, yards, front exterior</li><li>Avoid direct sunlight on the camera or reflective surfaces</li><li>Close all interior doors before scanning</li></ul><h2>Step 3: Capture the Property</h2><ul><li>Position the camera at your first scan point</li><li>Start capture from the app — the camera rotates automatically</li><li>Move to each subsequent point following your planned grid</li><li>The app shows alignment in real-time — green = aligned</li><li>A typical 2,000 sq ft home: <strong>30-60 scan positions, 45-90 minutes</strong></li></ul><h2>Step 4: Upload and Process</h2><ul><li>Upload scans via Wi-Fi to the Matterport Cloud</li><li>Cortex AI processes scans into 3D mesh, dollhouse view, and floor plans</li><li>Processing time: <strong>2-4 hours</strong> for a residential property</li><li>You will receive an email notification when ready</li></ul><h2>Step 5: Customize the Tour</h2><ul><li><strong>Add Mattertags</strong> — Interactive hotspots with text, photos, videos</li><li><strong>Set starting view</strong> — Choose the first room and angle visitors see</li><li><strong>Create a highlight reel</strong> — Guided video walkthrough of curated views</li><li><strong>Generate schematic floor plan</strong> — Cortex AI auto-generates 2D plans</li><li><strong>Add room labels</strong> — Mark Kitchen, Master Bedroom, etc.</li></ul><h2>Step 6: Publish and Share</h2><ul><li><strong>MLS Integration</strong> — Auto-syndicate to major MLS platforms</li><li><strong>Embed on website</strong> — Copy the iframe embed code</li><li><strong>Social media</strong> — Share tour link on Facebook, Instagram, LinkedIn</li><li><strong>Virtual Open House</strong> — Host live tours with Matterport Live Q&A</li><li><strong>QR Code</strong> — Generate QR code for yard signs</li><li><strong>Download assets</strong> — Export hi-res photos, GIFs, dollhouse view</li></ul>' WHERE slug = '3d-tours-matterport';

-- Comparison 1: Zillow AI vs Quantarium
UPDATE "Comparison" SET content = '<h2>Accuracy Comparison</h2><p>Zillow Zestimate reports a <strong>median error rate of 2.4%</strong> for on-market homes and 7.5% for off-market homes. Accuracy is best in dense urban areas (as low as 1.5%) and weakest in rural markets (10%+). Quantarium is independently rated among the <strong>top 5 AVMs for institutional accuracy</strong> in Freddie Mac assessments, with satellite imagery providing an edge where traditional data is sparse.</p><h2>Coverage and Data Sources</h2><p>Zillow covers <strong>100 million U.S. properties</strong> using public tax records, MLS data, and user submissions — updated within 24 hours. Quantarium covers <strong>150 million properties</strong> and integrates satellite imagery, geospatial data, and computer vision — updated weekly.</p><h2>Pricing and Accessibility</h2><p>Zillow Zestimate is <strong>completely free</strong> for consumers and agents via the Zillow website and app. Quantarium operates on an <strong>enterprise pricing model</strong> with custom quotes — typically $2,000-$5,000/month for mid-sized lenders.</p><h2>Recommendations</h2><p><strong>Choose Zillow AI if:</strong> you are an agent or investor who needs free, instant valuations in well-covered markets. <strong>Choose Quantarium if:</strong> you are a lender, insurer, or institutional investor who needs auditable, defensible valuations with satellite imagery analysis.</p>' WHERE slug = 'zillow-ai-vs-quantarium';

-- Comparison 2: Styldod vs Matterport
UPDATE "Comparison" SET content = '<h2>Core Functionality</h2><p>Styldod is an <strong>AI virtual staging and image enhancement platform</strong> — it digitally furnishes empty rooms and generates marketing content. Matterport is a <strong>3D spatial data platform</strong> — it creates immersive digital twins for virtual navigation. Many successful teams use both: Matterport for immersive tours and Styldod to enhance the still images from those tours.</p><h2>Cost Analysis</h2><p>Styldod: <strong>$16/image</strong> pay-as-you-go, or $99-$249/month subscription. Matterport: requires a compatible camera (smartphone = free, Pro3 = ~$6,000) plus $9.99-$309/month subscription.</p><h2>Buyer Engagement</h2><p>Styldod produces photorealistic still images in 30-60 minutes. Matterport creates interactive experiences where buyers navigate at their own pace — listings with Matterport generate <strong>49% more qualified leads</strong>. The tradeoff: Matterport takes 45-90 minutes on-site vs 5 minutes to photograph a room for Styldod.</p><h2>Best Use Cases</h2><p><strong>Styldod</strong>: vacant properties needing cost-effective MLS staging, quick listing enhancement, investment properties. <strong>Matterport</strong>: luxury listings, remote buyers, commercial real estate, properties with unique architecture that photos cannot fully convey.</p>' WHERE slug = 'styldod-vs-matterport';

-- Comparison 3: Revaluate vs CINC
UPDATE "Comparison" SET content = '<h2>Approach to Lead Generation</h2><p>Revaluate is a <strong>predictive analytics engine</strong> — it identifies homeowners most likely to move in 6-12 months by analyzing 2,000+ data points. CINC is a <strong>lead nurturing and conversion platform</strong> — it takes existing leads and uses AI to score, prioritize, and automatically nurture them through multi-channel follow-up.</p><h2>Accuracy and Performance</h2><p>Revaluate achieves <strong>70-80% move prediction accuracy</strong>, with identified leads converting at 2-3x the rate of purchased leads. CINC AI lead scoring delivers a <strong>30-40% improvement in lead-to-appointment conversion rates</strong> through real-time behavioral scoring.</p><h2>Automation</h2><p>Revaluate integrates with your CRM via API and delivers scored lead lists — it does not include built-in nurture sequences. CINC is a complete communication platform with email, SMS, and automated call reminders. Its AI Personal Assistant handles two-way SMS conversations automatically.</p><h2>Pricing</h2><p>Revaluate starts at <strong>$99/month</strong> (500 contacts). CINC starts at <strong>$400/month</strong> for the Professional plan.</p><h2>Final Verdict</h2><p>Revaluate excels at <strong>finding sellers no one else knows about</strong>. CINC excels at <strong>converting the leads you already have</strong>. The ideal setup: use both — Revaluate to identify likely movers and feed them into CINC for automated nurturing.</p>' WHERE slug = 'revaluate-vs-cinc';

-- Stat 1: AI Adoption
UPDATE "StatPage" SET content = '<h2>Key Findings</h2><p>The adoption of AI in real estate has reached a tipping point in 2025. <strong>47% of real estate agents now use AI tools</strong> in their daily workflow, up from 28% in 2023 — a 68% increase in two years.</p><h2>Adoption by Agent Type</h2><ul><li><strong>Top teams ($10M+ volume)</strong>: 78% use AI tools — often multiple platforms</li><li><strong>Solo agents</strong>: 41% use at least one AI tool</li><li><strong>New agents (licensed < 2 years)</strong>: 53% — younger professionals adopt AI early</li><li><strong>Commercial real estate</strong>: 35% — slower adoption due to fewer CRE-specific tools</li></ul><h2>Most Adopted AI Tools</h2><ul><li><strong>AVMs</strong>: 62% — most widely adopted AI category</li><li><strong>Virtual Staging</strong>: 48% — rapid growth driven by digital-first marketing</li><li><strong>Lead Scoring/CRM AI</strong>: 39%</li><li><strong>AI Content Generation</strong>: 34%</li><li><strong>Predictive Analytics for Leads</strong>: 28% — fastest-growing, up from 12% in 2023</li></ul><h2>Productivity Impact</h2><p>Agents using AI save <strong>8-12 hours per week</strong> on administrative tasks. Top adopters report <strong>3.2x more closed transactions</strong> than non-AI-using peers.</p>' WHERE slug = 'ai-adoption-real-estate-2025';

-- Stat 2: Market Size
UPDATE "StatPage" SET content = '<h2>Market Overview</h2><p>The global AI in real estate market is projected to grow from <strong>$5.8 billion in 2024 to $15 billion by 2027</strong>, representing a CAGR of approximately 37%.</p><h2>Market Segments</h2><ul><li><strong>Property Valuation & Analytics</strong>: $2.1B — largest segment</li><li><strong>Lead Gen & CRM</strong>: $1.5B — AI scoring and nurturing platforms</li><li><strong>Property Marketing</strong>: $1.2B — virtual staging, content generation</li><li><strong>Property Search</strong>: $0.9B — NLP search and recommendations</li><li><strong>Transaction Management</strong>: $0.7B — contract review and automation</li></ul><h2>Growth Drivers</h2><ul><li>Remote work increasing demand for virtual tours and digital transactions</li><li>Proliferation of property data from MLS, satellite, and IoT sensors</li><li>Consumer expectations for AI-powered, personalized experiences</li><li>Early AI adopters gaining measurable market share</li><li>$15B+ in Proptech venture funding in 2024</li></ul><h2>Regional Analysis</h2><p>North America: <strong>45% market share</strong>. Europe: 25%. Asia-Pacific: 20% (fastest-growing at 42% CAGR).</p>' WHERE slug = 'ai-real-estate-market-size';
